def cantor_numbering(N: int) -> str:
    # Initialize the numerator and denominator
    numerator, denominator = N, 1

    # Perform the Cantor pairing formula
    while N > 0:
        if N % 2 == 0:
            numerator, denominator = denominator, numerator + denominator + 1
        else:
