def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(message):
        return "Failed"
    if len(original) != len(set(original)):
        return "Failed"

    letter_mapping = {}
    for e, o in zip(set(encoded), original):
        if e in letter_mapping:
            if letter_mapping[e] != o:
                return "Failed"
            continue
        if len(letter_mapping) == len(set(original)):
            return "Failed"
        letter_mapping[e] = o

    decoded_message = ""

    for e in message:
        if e in letter_mapping:
            decoded_message += letter_mapping[e]
        else:
            return "Failed"

    return decoded_message

def decode(encoded: str, original: str, message: str) -> str:
    # Lengths of encoded, original, and message must match for decoding
    if len(encoded) != len(original) or len(encoded) != len(message):
        return "Failed"

    # Create a mapping from encoded letters to original letters
    mapping = {}
    for e, o in zip(encoded, original):
        if e not in mapping:
            mapping[e] = o
        elif mapping[e] != o:
            return "Failed"

    # Decode the message using the mapping
    decoded_message = ''.join(mapping.get(c, c) for c in message)

    return decoded_message

