def count_partitions(n: int, k: int, x: int) -> int:
    # Initialize the dynamic programming table
    partitions = [[0] * (k + 1) for _ in range(n + 1)]

    # Base cases
    for i in range(1, n + 1):
        partitions[i][0] = 0  # No partitions for parts needing to be 0

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i - x >= 0:
                partitions[i][j] = partitions[i][j - 1] + partitions[i - x][j]
            else:
                partitions[i][j] = partitions[i][j - 1]

    return partitions[n][k]

