    inorder_map = {item: idx for idx, item in enumerate(inorder)}

    def construct_tree(stop):
        if stop == "" and not stack:
            return
        val = stop[-1]
        root = Tree(val, None, None)

        # If this is not the stop value then traversing the elements from right to left
        right, left = tree_map[ind inorder_map[val] + 1 : inorder_map[val]]
        if right is not None:
            root.right = construct_tree(right)
        if left is not None:
            root.left = construct_tree(left)
        if stop == inorder:
            return root

        stack.append(root)
        stop = stop[:-1]

    stack = []
    tree_map = Counter(inorder)
    return construct_tree(postorder)

