    steps = 0

    # Create a queue and initialize it with the start state
    queue = deque([(A, steps)])
    visited = set()

    while queue and steps < max_steps:
        current, curr_steps = queue.popleft()
        if current == B:
            return curr_steps
        visited.add(current)

        # Generate all possible next states using the transformation rules
        for pattern, replacement in rules:
            if re.search(pattern, current):
                next_state = re.sub(pattern, replacement, current)
                if next_state not in visited:
                    queue.append((next_state, curr_steps + 1))

    return "NO ANSWER!"

