            return q[state]
        visited.add(state)

        # Try applying each rule to the current state
        for src, tgt in rules:
            if state.startswith(src) and state[0].isalpha() and state[0] != tgt[0]:
                new_state = state.replace(src, tgt, 1)
                if new_state not in visited and len(new_state) <= len(B) + 1:
                    q[new_state] = q[state] + 1

    # If the target state is not reachable within 10 steps
    return "NO ANSWER!"

