def max_herb_value(T, M, herbs):
    """Calculate the maximum total value of herbs that can be picked within a given time limit."""
    # Create a 2D list to store maximum values
    dp = [[0 for _ in range(M+1)] for _ in range(T+1)]

    # Fill the dp table
    for i in range(1, T+1):
        for j in range(1, M+1):
            value, time = herbs[j-1]
            if time <= i:
                dp[i][j] = max(dp[i][j-1], dp[i-time][j-1] + value)
            else:
                dp[i][j] = dp[i][j-1]

    # The maximum value that can be picked within the time limit
    return dp[T][M]

def max_herb_value(T, M, herbs):
    # Create a 2D dp table (answer_table) where answer_table[i][j] represents the maximum objective value that can be achieved by considering up to j herbs using the first i time units
    answer_table = np.zeros((M + 1, T + 1))

    # Fill the dp table
    for k in range(1, M + 1):
        for t in range(1, T + 1):
            # If the current herb can be picked within the current time unit, we compare picking it with not picking it
            if herbs[k - 1][0] <= t:
                answer_table[k][t] = max(herbs[k - 1][1] + answer_table[k - 1 - 1][t - herbs[k - 1][0]], answer_table[k - 1][t])
            else:
                # If the current herb cannot be picked within the current time unit, we copy the previous value
                answer_table[k][t] = answer_table[k - 1][t]

    # Return the maximum objective value
    return answer_table[M][T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a table to store the maximum volume that can be occupied with any subset of the first i items
    max_volume = [0] * (n + 1)

    # Base case: the maximum volume for 0 items is 0
    max_volume[0] = 0

    # Fill the table using dynamic programming
    for i in range(1, n + 1):
        for j in range(V - volumes[i - 1], -1, -1):
            if max_volume[j] + volumes[i - 1] <= V:
                max_volume[j + volumes[i - 1]] = max(max_volume[j + volumes[i - 1]], max_volume[j] + volumes[i - 1])

    # The minimum remaining space is the total capacity minus the maximum volume occupied
    min_remaining = V - max_volume[n]

    return min_remaining

